import { useState, useEffect, useRef, useCallback } from "react";
import {
  MapPin,
  Navigation,
  Loader,
  Crosshair,
  CheckSquare,
  Download,
} from "lucide-react";
import L from "leaflet";
import "leaflet/dist/leaflet.css";
import "leaflet-draw/dist/leaflet.draw.css";
import "leaflet-draw";
import tokml from "tokml";

import "../Style/map.css";
import HouseDetailsModal from "./HouseDetailsModal";

/* -----------------------------
   Helper: Download KML locally
----------------------------- */
const downloadKML = (kmlString, fileName) => {
  const blob = new Blob([kmlString], {
    type: "application/vnd.google-earth.kml+xml",
  });
  const link = document.createElement("a");
  link.href = URL.createObjectURL(blob);
  link.download = fileName;
  document.body.appendChild(link);
  link.click();
  document.body.removeChild(link);
  URL.revokeObjectURL(link.href);
};

export default function MapComponent() {
  const [location, setLocation] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [isModalOpen, setModalOpen] = useState(false);
  const [capturedLocation, setCapturedLocation] = useState(null);

  const mapRef = useRef(null);
  const mapInstanceRef = useRef(null);
  const markerRef = useRef(null);
  const circleRef = useRef(null);

  /* --- Store drawn shapes --- */
  const drawnItemsRef = useRef(null);

  /* -----------------------------
       Accurate GPS Fetch
  ----------------------------- */
  const fetchAccurateLocation = useCallback((onSuccess, onError) => {
    if (!navigator.geolocation) {
      onError("Geolocation is not supported.");
      return;
    }

    let bestAccuracy = Infinity;
    let attempts = 0;
    const maxAttempts = 5;

    const watchId = navigator.geolocation.watchPosition(
      (position) => {
        attempts++;
        if (position.coords.accuracy < bestAccuracy) {
          bestAccuracy = position.coords.accuracy;
          onSuccess({
            lat: position.coords.latitude,
            lng: position.coords.longitude,
            accuracy: position.coords.accuracy,
            altitude: position.coords.altitude,
          });
        }
        if (attempts >= maxAttempts || position.coords.accuracy < 10) {
          navigator.geolocation.clearWatch(watchId);
        }
      },
      (err) => {
        onError(err.message);
        navigator.geolocation.clearWatch(watchId);
      },
      { enableHighAccuracy: true, timeout: 10000, maximumAge: 0 }
    );
  }, []);

  /* -----------------------------
           Initial GPS Fetch
  ----------------------------- */
  useEffect(() => {
    setLoading(true);
    fetchAccurateLocation(
      (loc) => {
        setLocation(loc);
        setError(null);
        setLoading(false);
      },
      (err) => {
        setError(err);
        setLoading(false);
      }
    );
  }, [fetchAccurateLocation]);

  /* -----------------------------
        Map Initialization 
  ----------------------------- */
  useEffect(() => {
    if (location && mapRef.current && !mapInstanceRef.current) {
      const map = L.map(mapRef.current).setView([location.lat, location.lng], 19);

      L.tileLayer(
        "https://server.arcgisonline.com/ArcGIS/rest/services/World_Imagery/MapServer/tile/{z}/{y}/{x}",
        { attribution: "&copy; ESRI" }
      ).addTo(map);

      const userMarker = L.marker([location.lat, location.lng]).addTo(map);
      const accuracyCircle = L.circle([location.lat, location.lng], {
        radius: location.accuracy,
        color: "#4F46E5",
      }).addTo(map);

      mapInstanceRef.current = map;
      markerRef.current = userMarker;
      circleRef.current = accuracyCircle;

      /* --- Leaflet Draw Controls --- */
      const drawnItems = new L.FeatureGroup();
      map.addLayer(drawnItems);
      drawnItemsRef.current = drawnItems;

      const drawControl = new L.Control.Draw({
        edit: { featureGroup: drawnItems },
        draw: { polygon: true, rectangle: true, polyline: true, circle: false },
      });
      map.addControl(drawControl);

      map.on(L.Draw.Event.CREATED, (event) => {
        drawnItems.addLayer(event.layer);
      });
    }
  }, [location]);

  /* -----------------------------
      UPDATE markers when GPS moves
  ----------------------------- */
  useEffect(() => {
    if (location && mapInstanceRef.current) {
      markerRef.current.setLatLng([location.lat, location.lng]);
      circleRef.current.setLatLng([location.lat, location.lng]);
    }
  }, [location]);

  const handleProceedClick = () => {
    if (!location) return alert("Location missing");
    setCapturedLocation(location);
    setModalOpen(true);
  };

  /* ------------------------------------------------------------
      FINAL VERSION — SAVE SURVEY + UPLOAD KML FILE TO BACKEND
  ------------------------------------------------------------- */
  const handleSaveSurvey = async (formData) => {
    try {
      /* 1️⃣ Build POINT KML */
      const kmlString = `<?xml version="1.0" encoding="UTF-8"?>
<kml xmlns="http://www.opengis.net/kml/2.2">
 <Placemark>
   <name>${formData.propertyName || "Survey Point"}</name>
   <Point>
     <coordinates>${capturedLocation.lng},${capturedLocation.lat},0</coordinates>
   </Point>
 </Placemark>
</kml>`;

      /* 2️⃣ Convert KML to Blob (file) */
      const kmlBlob = new Blob([kmlString], {
        type: "application/vnd.google-earth.kml+xml",
      });

      /* 3️⃣ Upload FILE to backend GridFS */
      const fd = new FormData();
      fd.append(
        "kmlFile",
        kmlBlob,
        `${formData.houseNumber || "survey"}.kml`
      );

      const uploadRes = await fetch(
        "http://localhost:5000/api/upload-kml-gridfs",
        {
          method: "POST",
          body: fd,
        }
      );

      const uploadData = await uploadRes.json();
      if (!uploadRes.ok) throw new Error(uploadData.message);

      const fileId = uploadData.fileId;

      /* 4️⃣ Build survey object to save in DB */
      const surveyData = {
        ...formData,
        location: {
          type: "Point",
          coordinates: [capturedLocation.lng, capturedLocation.lat],
        },
        accuracy: capturedLocation.accuracy,
        kmlFileId: fileId, // IMPORTANT
      };

      /* 5️⃣ Store survey in DB */
      const saveRes = await fetch("http://localhost:5000/api/save-survey", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(surveyData),
      });

      const saveData = await saveRes.json();
      if (!saveRes.ok) throw new Error(saveData.message);

      /* 6️⃣ Optional: Download locally too */
      downloadKML(
        kmlString,
        `${formData.houseNumber || "survey"}.kml`
      );

      alert("Survey saved + KML uploaded!");
    } catch (err) {
      console.error(err);
      alert("Error: " + err.message);
    }
  };

  return (
    <div className="map-container">
      {/* ===== UI Code unchanged ===== */}
      <button onClick={handleProceedClick} className="proceed-button">
        <CheckSquare size={18} /> Proceed to Survey
      </button>

      <HouseDetailsModal
        isOpen={isModalOpen}
        onClose={() => setModalOpen(false)}
        onSave={handleSaveSurvey}
        capturedLocation={capturedLocation}
      />
    </div>
  );
}
